const message = $('Zalo Message').first()?.json?.message ?? {};
const chat = message.chat ?? {};

const pick = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};

const chatId = pick(chat.id ?? message.chatId ?? message.from?.id ?? message.sender?.id);
if (!chatId) {
  throw new Error('Missing Zalo chat ID');
}

return [{
  json: {
    chat_id: chatId,
    user_text: pick(message.text) ?? '',
    user_name: pick(chat.name ?? message.from?.display_name ?? message.from?.name ?? message.sender?.display_name ?? message.sender?.name),
    event_name: pick($('Zalo Message').first()?.json?.event_name ?? $('Zalo Message').first()?.json?.event),
    received_at: new Date().toISOString(),
  },
}];

const normalized = $('Normalize Message').first()?.json ?? {};
const approvedReply = $('Pre-Send Decision').first()?.json ?? {};

return [{
  json: {
    chat_id: normalized.chat_id ?? null,
    user_text: normalized.user_text ?? '',
    bot_output: approvedReply.output ?? '',
    user_name: normalized.user_name ?? null,
    received_at: normalized.received_at ?? new Date().toISOString(),
  },
}];

