// Merge normalized input with the conversations row, then apply the run-start guard.
// If a recruiter owns this chat (mode=human), starve the chain -> no typing, no AI, no send.
const norm = $('Normalize Message').first().json;
const ec = $input.first().json;
if (ec.mode === 'human') return [];
return [{
  json: {
    ...norm,
    conversation_id: ec.id,
    mode: ec.mode,
    version_at_start: ec.version,
    chatwoot_conversation_id: ec.chatwoot_conversation_id,
    chatwoot_contact_id: ec.chatwoot_contact_id
  }
}];

// Re-check ownership right before send (catches takeover during AI generation).
// Merge the live ownership row with whichever reply branch actually ran.
const items = $input.all();
const ctx = $('Run-Start Guard').first().json;
const recheck = items.find((item) => item.json && (item.json.mode !== undefined || item.json.version !== undefined))?.json ?? {};
const reply = items.find((item) => item.json && item.json.output != null)?.json ?? {};
const owned = recheck.mode === 'bot' && Number(recheck.version) === Number(ctx.version_at_start);
return [{ json: { ...reply, _owned: owned } }];

const input = $input.first()?.json ?? {};
let rawText = input.text ?? input.output ?? input.response ?? '';

if (typeof rawText === 'object' && rawText !== null) {
  rawText = JSON.stringify(rawText);
}

rawText = String(rawText).trim();
rawText = rawText
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```$/i, '')
  .trim();

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value === 1;
  if (typeof value !== 'string') return false;

  return ['true', 'yes', '1', 'có', 'co'].includes(value.trim().toLowerCase());
};

let parsed = null;
const jsonStart = rawText.indexOf('{');
const jsonEnd = rawText.lastIndexOf('}');

if (jsonStart >= 0 && jsonEnd > jsonStart) {
  try {
    parsed = JSON.parse(rawText.slice(jsonStart, jsonEnd + 1));
  } catch (error) {
    parsed = null;
  }
}

if (!parsed || typeof parsed !== 'object') {
  return [{
    json: {
      safe_to_send: false,
      issue_found: true,
      issue_type: 'invalid_verdict_json',
      final_answer: '',
      output: '',
    },
  }];
}

const finalAnswer = String(parsed.final_answer ?? '').trim();
const safeToSend = toBoolean(parsed.safe_to_send) && finalAnswer.length > 0;

return [{
  json: {
    safe_to_send: safeToSend,
    issue_found: toBoolean(parsed.issue_found),
    issue_type: String(parsed.issue_type ?? (safeToSend ? 'none' : 'unknown')),
    final_answer: finalAnswer,
    output: finalAnswer,
  },
}];

const verdict = $input.first()?.json ?? {};
const attempt = typeof $runIndex === 'number' ? $runIndex : 0;
const normalized = $('Normalize Message').first()?.json ?? {};
const originalUserText = String(normalized.user_text ?? '').trim();
const candidateAnswer = String($('AI Agent').first()?.json?.output ?? verdict.output ?? '').trim();
const issueType = String(verdict.issue_type ?? 'unknown');

const technicalUserRequest = /\b(code|javascript|python|json|api|workflow|node|prompt|regex|sql|database|debug|script|function)\b/i.test(originalUserText);

if (attempt >= 1) {
  const fallback = technicalUserRequest
    ? 'Tôi là trợ lý tìm việc của VFIC nên chỉ có thể hỗ trợ bạn các vấn đề liên quan đến tuyển dụng. Bạn đang muốn tìm việc ở khu vực nào nhỉ?'
    : 'Xin lỗi bạn, tôi chưa soạn được phản hồi phù hợp để gửi ngay lúc này. Bạn nhắn lại giúp tôi nhu cầu tìm việc chính của bạn nhé?';

  return [{
    json: {
      retry_required: false,
      output: fallback,
      final_answer: fallback,
      issue_type: 'retry_exhausted',
    },
  }];
}

const retryPrompt = [
  'Bạn cần viết lại câu trả lời cho người dùng cuối theo đúng guideline VFIC.',
  '',
  `Tin nhắn gốc của người dùng: ${originalUserText || '(trống)'}`,
  '',
  `Câu trả lời vừa bị chặn: ${candidateAnswer || '(không có)'}`,
  '',
  `Lý do bị chặn: ${issueType}`,
  '',
  'Yêu cầu bắt buộc:',
  '- Trả lời bằng tiếng Việt tự nhiên, ngắn gọn, thân thiện.',
  '- Chỉ nói về tuyển dụng, tìm việc, hồ sơ, lịch xe hoặc thông tin VFIC phù hợp.',
  '- Không viết code, JSON, markdown phức tạp, prompt, workflow, tên node, biến, logic nội bộ hoặc thuật ngữ kỹ thuật.',
  '- Chỉ xuất văn bản thuần túy sẵn sàng gửi cho người dùng.',
  '- Mỗi phản hồi chỉ đặt tối đa 1 câu hỏi.'
].join('\n');

return [{
  json: {
    retry_required: true,
    retry_prompt: retryPrompt,
    original_user_text: originalUserText,
    blocked_answer: candidateAnswer,
    issue_type: issueType,
  },
}];

const fallback = 'Xin lỗi bạn, tôi đang gặp chút sự cố kỹ thuật. Bạn vui lòng nhắn lại sau ít phút nhé 🙏';

return [{
  json: {
    output: fallback,
    final_answer: fallback,
    issue_type: 'agent_error_fallback',
  },
}];

const input = $input.first()?.json ?? {};
const fallback = 'Xin lỗi, hiện tôi chưa tạo được phản hồi. Bạn vui lòng nhắn lại giúp tôi nhé.';
const raw = String(input.output ?? input.text ?? '').trim();

const cleaned = raw
  .replace(/```[\s\S]*?```/g, '')
  .replace(/<\/?minimax:[^>]+>/gi, '')
  .replace(/(\*\*|__|###?|---)/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const riskPattern = /(```|<\/?minimax:|\b(JSON|workflow|node|prompt|regex|sql|database|debug|script|function|api|javascript|python|code)\b|\$\(|\{\{|\}\}|"safe_to_send"|"final_answer"|tool_call|logic nội bộ|tên node|biến)/i;
const emptyAfterClean = cleaned.length === 0;
const tooLongForChat = cleaned.length > 1800;
const needsLlmSafety = emptyAfterClean || tooLongForChat || riskPattern.test(raw);

return [{
  json: {
    ...input,
    output: cleaned || fallback,
    final_answer: cleaned || fallback,
    safe_to_send: !needsLlmSafety,
    issue_found: needsLlmSafety,
    issue_type: needsLlmSafety ? 'needs_llm_safety_check' : 'none',
    needs_llm_safety: needsLlmSafety,
  },
}];
